package fr.gemsofrod.encyclopedie.data

/** Traducciones españolas del nombre y de los textos descriptivos de los fósiles. */
object FossileTranslationsEs {
    val data: Map<String, FossileTranslation> = mapOf(
        "fossile-ammonite-madagascar" to FossileTranslation(
            nom = "Ammonite de Madagascar",
            descriptionCourte = "El fósil más emblemático, espiral calcificada de un cefalópodo marino extinguido junto con los dinosaurios.",
            descriptionLongue = "Las ammonites son cefalópodos marinos emparentados con el nautilo y el pulpo actuales, cuya concha enrollada en espiral se fosilizó por millones a lo largo de las antiguas costas del Cretácico malgache. Serradas y pulidas, revelan sus tabiques internos (suturas) en motivos geométricos apreciados tanto en decoración como en joyería de entrada de gama.",
            interetJoaillerie = "Bueno: discos pulidos en colgantes, ejemplares enteros para decoración y colección de iniciación."
        ),
        "fossile-ammolite" to FossileTranslation(
            nom = "Ammolita",
            descriptionCourte = "El único fósil oficialmente reconocido como gema, cuya iridiscencia rivaliza con el ópalo.",
            descriptionLongue = "La ammolita procede de un yacimiento único en el mundo, a lo largo del río St. Mary's en Alberta, donde el nácar de aragonito de ciertas ammonites gigantes se preservó intacto en lugar de recristalizarse en calcita. El resultado es una iridiscencia espectacular, tan fina y frágil que casi siempre se protege con un doblete o triplete antes del engaste. La CIBJO la clasificó oficialmente como gema orgánica en 1981, junto a la perla, el coral y el ámbar.",
            interetJoaillerie = "Elevado: cabujones, dobletes y tripletes engastados, muy buscada por su iridiscencia comparable al ópalo."
        ),
        "fossile-orthocere" to FossileTranslation(
            nom = "Ortocera",
            descriptionCourte = "Un cefalópodo de concha recta en forma de cono alargado, antepasado lejano del calamar.",
            descriptionLongue = "A diferencia de la ammonite enrollada, la ortocera poseía una concha cónica recta y tabicada, en la que el animal ajustaba su flotabilidad como todavía hace el nautilo en la actualidad. Las losas calizas marroquíes, repletas de secciones de ortoceras y otros invertebrados marinos, se utilizan ampliamente en pavimentos y objetos decorativos pulidos.",
            interetJoaillerie = "Moderado: esencialmente decoración (losas, lavabos, bandejas) más que joyería."
        ),
        "fossile-goniatite" to FossileTranslation(
            nom = "Goniatita",
            descriptionCourte = "El antepasado directo de la ammonite, reconocible por sus tabiques internos en zigzag más simples.",
            descriptionLongue = "Aparecidas antes que las ammonites en el Devónico, las goniatitas comparten la misma silueta espiralada pero presentan líneas de sutura internas más simples, en forma de dientes de sierra. Marruecos extrae de ellas ejemplares notablemente bien conservados, a menudo vendidos en bruto o ligeramente pulidos para revelar la concha sin borrar su relieve natural.",
            interetJoaillerie = "Moderado: piezas de colección y colgantes en bruto pulidos."
        ),
        "fossile-trilobite-elrathia" to FossileTranslation(
            nom = "Trilobites Elrathia kingii",
            descriptionCourte = "El trilobites más comúnmente hallado en el mundo, extraído por millones de un mismo yacimiento de Utah.",
            descriptionLongue = "Elrathia kingii es un pequeño trilobites del Cámbrico medio extraído en cantidades considerables de los esquistos de la formación Wheeler, en Utah, un yacimiento tan productivo que suministra casi la totalidad de los trilobites vendidos en el comercio mundial. Su característica segmentación tricéfala (cabeza, tórax, pigidio) lo convierte en un excelente ejemplar didáctico para comprender la anatomía de este grupo de artrópodos extinguido desde finales del Pérmico.",
            interetJoaillerie = "Bajo: esencialmente colección, a veces montado en bruto en colgante protegido."
        ),
        "fossile-trilobite-phacops" to FossileTranslation(
            nom = "Trilobites Phacops rana",
            descriptionCourte = "El trilobites estrella de los coleccionistas, célebre por sus grandes ojos compuestos de facetas de calcita.",
            descriptionLongue = "Phacops rana es sin duda el trilobites más buscado por los coleccionistas por sus ojos hemisféricos prominentes, formados por decenas de lentes individuales de calcita, uno de los primeros sistemas ópticos complejos de la evolución. Los talleres marroquíes de Alnif se han especializado en la preparación minuciosa de estas piezas, liberadas con aguja neumática para revelar el relieve completo del animal enrollado sobre sí mismo en posición de defensa.",
            interetJoaillerie = "Bajo: esencialmente colección y decoración."
        ),
        "fossile-trilobite-calymene" to FossileTranslation(
            nom = "Trilobites Calymene",
            descriptionCourte = "Un trilobites clásico y asequible, a menudo hallado enrollado como una cochinilla fósil.",
            descriptionLongue = "El género Calymene, ampliamente extendido en los yacimientos marroquíes y conocido durante mucho tiempo en Inglaterra con el apodo de «Dudley bug», se distingue por su capacidad de enrollarse completamente sobre sí mismo en posición defensiva, exactamente como una cochinilla actual. Este comportamiento fosilizado «en bola» es uno de los ejemplares de iniciación más habituales para los coleccionistas principiantes.",
            interetJoaillerie = "Bajo: colección y decoración."
        ),
        "fossile-dent-megalodon" to FossileTranslation(
            nom = "Diente de megalodón",
            descriptionCourte = "El diente del tiburón más grande que jamás haya existido, capaz de superar los 18 cm de altura.",
            descriptionLongue = "El megalodón, un tiburón gigante extinguido hace unos 3,6 millones de años, podía alcanzar entre 15 y 18 metros de longitud. Sus dientes triangulares masivos, dentados como los del gran tiburón blanco actual pero mucho más grandes, se mineralizaron en el sedimento adquiriendo tonalidades variadas según los yacimientos. Las piezas más hermosas, simétricas y sin desgaste, alcanzan precios elevados tanto en colección como en joyería en bruto.",
            interetJoaillerie = "Elevado: colgantes en bruto engastados en garras, muy demandados en joyería decorativa."
        ),
        "fossile-os-dinosaure-gembone" to FossileTranslation(
            nom = "Hueso de dinosaurio agatizado (\"gembone\")",
            descriptionCourte = "Un hueso de dinosaurio reemplazado por completo, molécula a molécula, por ágata coloreada.",
            descriptionLongue = "En ciertos yacimientos del Jurásico estadounidense, los huesos de dinosaurio enterrados sufrieron una silicificación completa: la materia ósea original se disolvió y fue reemplazada progresivamente por sílice coloreada, preservando fielmente la estructura celular porosa del hueso mientras la transformaba en ágata pulible. El resultado, apodado «gembone» por los lapidarios, combina el valor científico de un auténtico fósil de dinosaurio con el atractivo estético de una piedra semipreciosa de motivos únicos.",
            interetJoaillerie = "Elevado: cabujones muy buscados, motivo celular único imposible de imitar."
        ),
        "fossile-poisson-green-river" to FossileTranslation(
            nom = "Pez fósil de Green River",
            descriptionCourte = "Bancos enteros de pequeños peces inmovilizados en una caliza lacustre de una finura excepcional.",
            descriptionLongue = "El antiguo lago Fósil de Wyoming preservó, en sedimentos finamente laminados, decenas de miles de peces de agua dulce en un estado de conservación excepcional: escamas, aletas y a veces incluso contenido estomacal intactos. La formación de Green River es hoy uno de los yacimientos de vertebrados fósiles más prolíficos del mundo, explotado a cielo abierto y vendido en losas serradas para decoración.",
            interetJoaillerie = "Moderado: losas enmarcadas, objetos de decoración más que joyas."
        ),
        "fossile-dent-mosasaure" to FossileTranslation(
            nom = "Diente de mosasaurio",
            descriptionCourte = "El diente cónico de un gran reptil marino depredador, primo lejano de los varanos actuales.",
            descriptionLongue = "Los mosasaurios eran grandes reptiles marinos depredadores, emparentados con los varanos actuales, que dominaban los mares a finales del Cretácico, justo antes de la extinción que también acabó con los dinosaurios no avianos. Los fosfatos marroquíes de Khouribga, mundialmente conocidos por su riqueza en vertebrados marinos fósiles, entregan regularmente dientes cónicos bien conservados, apreciados por los coleccionistas por su forma espectacular.",
            interetJoaillerie = "Moderado: colgantes en bruto, fuerte valor de colección."
        ),
        "fossile-ivoire-mammouth" to FossileTranslation(
            nom = "Marfil fósil de mamut",
            descriptionCourte = "El marfil de un gigante desaparecido de la última era glacial, liberado por el deshielo del permafrost siberiano.",
            descriptionLongue = "El calentamiento progresivo del permafrost siberiano libera cada año colmillos de mamut lanudo, a veces notablemente conservados tras decenas de miles de años enterrados en el hielo. Este comercio, legal y regulado a diferencia del marfil de elefante moderno, abastece a escultores y joyeros con un material de textura y grano cercanos al marfil vivo, a veces realzado con tonalidades azul-verdosas espectaculares debidas a una mineralización superficial de fosfato de hierro (vivianita).",
            interetJoaillerie = "Elevado: esculturas, joyas, incrustaciones; comercio legal regulado, a diferencia del marfil de elefante actual."
        ),
        "fossile-bois-petrifie" to FossileTranslation(
            nom = "Madera petrificada",
            descriptionCourte = "Un tronco de árbol entero transformado en piedra, anillo por anillo, por infiltración de sílice.",
            descriptionLongue = "Cuando un tronco cae y queda rápidamente enterrado en un sedimento saturado de sílice, el agua rica en silicatos se infiltra progresivamente en la estructura celular de la madera y la reemplaza, fibra a fibra, antes de que la descomposición la borre. El resultado conserva la textura, los anillos de crecimiento e incluso a veces los insectos que horadaron la corteza, adquiriendo al mismo tiempo la dureza y el pulido del ágata, de ahí su popularidad tanto en joyería como en grandes piezas de mobiliario decorativo.",
            interetJoaillerie = "Elevado: cabujones y joyas, muy demandada también en decoración (bandejas, tableros de mesa)."
        ),
        "fossile-fougere" to FossileTranslation(
            nom = "Helecho fósil",
            descriptionCourte = "La delicada huella carbonosa de un helecho de los inmensos bosques pantanosos del Carbonífero.",
            descriptionLongue = "Los vastos pantanos boscosos del Carbonífero, origen de la mayoría de los yacimientos de carbón actuales, dejaron en sus esquistos arcillosos innumerables huellas de helechos y helechos con semillas, preservadas en forma de una fina película de carbono. Estas placas, obtenidas al hender la roca a lo largo del plano de la hoja fosilizada, revelan nervaduras de una finura notable para vegetales de más de 300 millones de años de antigüedad.",
            interetJoaillerie = "Bajo: esencialmente colección y decoración mural enmarcada."
        ),
        "fossile-ambre-baltique" to FossileTranslation(
            nom = "Ámbar del Báltico",
            descriptionCourte = "La resina fosilizada de bosques de coníferas desaparecidos, la gema orgánica más antigua de la joyería humana.",
            descriptionLongue = "El ámbar báltico se formó hace unos 44 millones de años a partir de la resina de coníferas gigantes, hoy desaparecidas, cuyos bosques cubrían el norte de Europa. Arrastrado por los cursos de agua y luego depositado en las playas del mar Báltico tras las tormentas, ha sido trabajado e intercambiado por la humanidad desde la Edad del Bronce; las rutas comerciales del ámbar se cuentan entre las vías de intercambio documentadas más antiguas de Europa.",
            interetJoaillerie = "Elevado: joyería tradicional del norte de Europa desde la Edad del Bronce."
        ),
        "fossile-ambre-inclusion" to FossileTranslation(
            nom = "Ámbar con inclusión de insecto",
            descriptionCourte = "Un mosquito, una hormiga o una flor inmovilizados para siempre en una gota de resina convertida en piedra.",
            descriptionLongue = "El ámbar dominicano, más joven y generalmente más transparente que el ámbar báltico, debe su fama a la riqueza excepcional de sus inclusiones: insectos, arañas, pequeñas flores e incluso, ocasionalmente, pequeños vertebrados quedan atrapados con un lujo de detalles que ha hecho célebre a este fósil mucho más allá de los círculos de coleccionistas, popularizado en particular por la ficción en torno al ADN preservado en el ámbar.",
            interetJoaillerie = "Elevado: cada inclusión es única, fuerte valor añadido en joyería de colección."
        ),
        "fossile-copal" to FossileTranslation(
            nom = "Copal",
            descriptionCourte = "La etapa «adolescente» del ámbar: una resina fósil demasiado joven para haber polimerizado por completo.",
            descriptionLongue = "El copal es una resina vegetal que aún no ha completado la lenta polimerización química que, a lo largo de millones de años, transforma una resina en verdadero ámbar. Más blando, más soluble en disolventes y a menudo más transparente, a veces se vende indebidamente como ámbar; una sencilla prueba con acetona (que vuelve pegajoso al copal en superficie, sin efecto sobre el ámbar verdadero) permite distinguirlos.",
            interetJoaillerie = "Moderado: joyería artesanal local, que debe distinguirse claramente del ámbar en una ficha de venta."
        ),
        "fossile-corail-agatise" to FossileTranslation(
            nom = "Coral fósil agatizado",
            descriptionCourte = "Un arrecife de coral entero convertido en ágata, cada pólipo inmovilizado en una flor de sílice.",
            descriptionLongue = "En Florida, antiguos arrecifes de coral quedaron silicificados por aguas subterráneas ricas en sílice, y cada pólipo de coral fue reemplazado fielmente por calcedonia conservando su característica estructura radiada. Una vez cortado y pulido, el resultado evoca motivos florales naturales tan regulares que a veces se confunde con una creación artificial; fue designado piedra oficial del estado de Florida en 1979.",
            interetJoaillerie = "Elevado: cabujones de motivos florales únicos, apreciados en joyería regional e internacional."
        ),
        "fossile-oursin" to FossileTranslation(
            nom = "Erizo de mar fósil",
            descriptionCourte = "El caparazón calcáreo de simetría perfecta de un erizo de mar, llevado durante mucho tiempo como talismán.",
            descriptionLongue = "Los caparazones (testas) de erizos de mar fósiles, con su característica simetría radial de cinco brazos, se encuentran en abundancia en las calizas cretácicas de Europa y el norte de África. Apodados «panes de hada» o «piedras de San Pedro» en el folclore europeo, se conservaban tradicionalmente como amuleto o protección del hogar mucho antes de ser estudiados científicamente.",
            interetJoaillerie = "Bajo a moderado: llevado tradicionalmente como colgante en bruto («piedra de San Pedro» o «pan de hada» en Europa)."
        ),
        "fossile-crinoide" to FossileTranslation(
            nom = "Crinoideo (entroco)",
            descriptionCourte = "Los anillos calcáreos apilados del tallo de un «lirio de mar», un equinodermo fijo y no una planta.",
            descriptionLongue = "A pesar de su engañoso nombre de «lirio de mar», el crinoideo es un animal equinodermo emparentado con el erizo de mar y la estrella de mar, fijado al fondo marino mediante un largo tallo articulado. Este tallo, compuesto de anillos calcáreos apilados como monedas, se desarticula fácilmente tras la muerte del animal y se encuentra en abundancia en ciertas calizas, formando lo que los geólogos llaman una caliza entrocal una vez pulida en losa.",
            interetJoaillerie = "Moderado: losas y objetos decorativos más que joyas, a veces cabujones para los tallos aislados."
        ),
        "fossile-stromatolite" to FossileTranslation(
            nom = "Estromatolito fósil",
            descriptionCourte = "Las huellas de vida más antiguas conocidas en la Tierra, construidas capa por capa por colonias de bacterias.",
            descriptionLongue = "Los estromatolitos no son los restos de un organismo individual, sino estructuras sedimentarias laminadas, construidas pacientemente capa tras capa por colonias de cianobacterias que atrapan el sedimento y precipitan carbonato de calcio. Algunos yacimientos australianos se cuentan entre las huellas de vida más antiguas identificadas en la Tierra, con más de 3.400 millones de años; un testimonio directo de los primerísimos ecosistemas del planeta, hoy pulido en losas decorativas por su motivo concéntrico único.",
            interetJoaillerie = "Bajo a moderado: losas decorativas, cabujones ocasionales para las variedades silicificadas."
        ),
        "fossile-belemnite" to FossileTranslation(
            nom = "Belemnita",
            descriptionCourte = "El «rostro» fosilizado de un calamar prehistórico, confundido durante mucho tiempo en el folclore con una piedra de rayo.",
            descriptionLongue = "Lo que se encuentra fosilizado no es el animal entero sino su rostro, una estructura calcárea interna rígida que servía de contrapeso y sostén al cuerpo blando del cefalópodo, primo extinguido de los calamares actuales. Su forma cónica y alargada, a menudo confundida por el folclore popular europeo con una «piedra de rayo» caída del cielo, lo convierte en un fósil fácilmente reconocible incluso por los no especialistas.",
            interetJoaillerie = "Bajo: colección, colgantes en bruto ocasionales."
        ),
    )
}
